'use strict';
// Public app: no personal dataset is bundled or requested from a server.
const $ = id => document.getElementById(id);
const KEY = 'mhl-visitor-plan-v1';
const TEMPLATE = {meta:{version:1},loan:{lender:'',interestType:'Floating',projectCost:0,sanctioned:0,disbursed:0,outstanding:0,rate:0,tenureYears:15,repaymentStart:'',extraMonthly:0,notes:''},contractor:[],indirectExpenses:[],disbursements:[],prepayments:[],budget:[],indirectBudget:[],funding:[],processing:{stage:''},emergency:{monthlyEssentials:0,targetMonths:0,currentFund:0},family:[],insurance:[],actions:[],strategy:{},life:{educationMonthly:0,parentsCareMonthly:0,healthReserve:0,annualInflation:5}};
let plan = null, tab = 'overview', source = 'blank';
const money = n => '₹' + (Number(n)||0).toLocaleString('en-IN',{maximumFractionDigits:0});
const sum = (rows, field='amount') => (Array.isArray(rows)?rows:[]).reduce((a,x)=>a+(Number(x[field])||0),0);
const esc = v => String(v??'').replace(/[&<>"']/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const asArray = v => Array.isArray(v)?v:[];
function validate(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('This is not a loan-plan JSON object.');if(raw.loan&&!['object'].includes(typeof raw.loan))throw Error('The loan field must be an object.');for(const k of ['contractor','indirectExpenses','disbursements','prepayments','budget','indirectBudget','funding','family','insurance','actions'])if(raw[k]!=null&&!Array.isArray(raw[k]))throw Error(`${k} should be a list.`);return {...structuredClone(TEMPLATE),...raw,loan:{...TEMPLATE.loan,...(raw.loan||{})}}}
function notify(text){$('notice').textContent=text;}
function show(p,label){plan=validate(p);source=label;document.querySelector('#workspace').hidden=false;document.querySelector('#intro').hidden=true;$('source-label').textContent=label==='blank'?'A fresh plan, saved on this device':label==='import'?'Imported JSON · kept in this browser':'Saved on this device';render();$('workspace').scrollIntoView({behavior:'smooth'});}
function save(){if(window.planOrigin==='owner'){notify('This private plan is read-only. No changes were saved.');return}try{localStorage.setItem(KEY,JSON.stringify(plan));notify('Saved on this device. Export JSON to keep a backup.')}catch{notify('Browser storage is unavailable. Export JSON now to keep a copy.')}render()}
function download(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
if($('start')) $('start').onclick=()=>{show(TEMPLATE,'blank');save()};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>5_000_000){alert('This file is larger than 5 MB. Please choose a smaller JSON plan.');return}try{show(JSON.parse(await f.text()),'import');save()}catch(err){alert('Could not open this plan: '+err.message)}e.target.value=''};
$('template').onclick=()=>download(TEMPLATE,'my-home-loan-empty-template.json');$('download').onclick=()=>{if(window.planOrigin==='owner'){notify('Private-plan export is disabled in this preview.');return}if(plan)download(plan,'my-home-loan-backup.json')};$('reset').onclick=()=>{if(window.planOrigin==='owner'){notify('Use Sign out to close your private plan.');return}if(!confirm('Close this plan and delete its saved copy from this browser? Export a backup first if you need it.'))return;localStorage.removeItem(KEY);plan=null;$('workspace').hidden=true;$('intro').hidden=false;window.scrollTo({top:0,behavior:'smooth'})};
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
function card(label,value,sub=''){return `<div class="card"><label>${esc(label)}</label><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`}
function bars(rows){if(!rows.length)return '<div class="empty">No entries yet. Import a JSON plan to see the breakdown.</div>';const max=Math.max(1,...rows.map(x=>Number(x.value)||0));return rows.map(x=>`<div class="bar-row"><span>${esc(x.label)}</span><div class="bar"><i style="width:${Math.min(100,Math.max(0,(Number(x.value)||0)/max*100))}%"></i></div><b>${esc(money(x.value))}</b></div>`).join('')}
function table(rows,fields){if(!rows.length)return '<div class="empty">No records in this section yet.</div>';return `<div class="table-wrap"><table><thead><tr>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${fields.map(f=>`<td>${esc(f.render?f.render(row):row[f.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
const cost=()=>sum(plan.contractor)+sum(plan.indirectExpenses);
function overview(){const l=plan.loan,costPlanned=sum(plan.budget,'planned')+sum(plan.indirectBudget,'planned'),fund=sum(plan.funding,'planned'),out=Number(l.outstanding)||0,rate=Number(l.rate)||0;return `<div class="cards">${card('Project budget',money(costPlanned),'Construction + indirect')}${card('Paid to date',money(cost()),'Contractor + indirect')}${card('Loan outstanding',money(out),'Entered balance')}${card('Remaining budget',money(costPlanned-cost()),'Plan minus paid')}</div><div class="grid2"><div class="panel"><h3>Funding plan</h3>${bars(asArray(plan.funding).map(x=>({label:x.source||'Other',value:x.planned})))}</div><div class="panel"><h3>What needs attention</h3><p>Funding gap: <strong>${money(costPlanned-fund)}</strong> · ${costPlanned>fund?'planned budget exceeds listed sources':'planned sources cover listed budget'}</p><p>Processing stage: <span class="pill">${esc(plan.processing?.stage||'Not set')}</span></p><p>Interest rate: <strong>${esc(rate)}%</strong> · Entered lender: <strong>${esc(l.lender||'Not set')}</strong></p><p class="hint">Figures are only as current as the JSON you imported or the edits on this device.</p></div></div>`}
function ledger(){return `<div class="cards">${card('Contractor paid',money(sum(plan.contractor)),`${asArray(plan.contractor).length} entries`)}${card('Indirect costs',money(sum(plan.indirectExpenses)),`${asArray(plan.indirectExpenses).length} entries`)}${card('Disbursed',money(sum(plan.disbursements)),'Recorded disbursements')}${card('Prepaid',money(sum(plan.prepayments)),'Recorded extra payments')}</div><div class="panel"><h3>Contractor payments</h3>${table(asArray(plan.contractor),[{key:'date',label:'Date'},{key:'payee',label:'Payee'},{key:'category',label:'Category'},{key:'source',label:'Source'},{key:'amount',label:'Amount',render:x=>money(x.amount)}])}</div><div class="panel"><h3>Indirect expenses</h3>${table(asArray(plan.indirectExpenses),[{key:'date',label:'Date'},{key:'description',label:'Description'},{key:'category',label:'Category'},{key:'amount',label:'Amount',render:x=>money(x.amount)}])}</div>`}
function plans(){return `<div class="grid2"><div class="panel"><h3>Construction budget</h3>${bars(asArray(plan.budget).map(x=>({label:x.category||'Other',value:x.planned})))}</div><div class="panel"><h3>Indirect cost budget</h3>${bars(asArray(plan.indirectBudget).map(x=>({label:x.category||'Other',value:x.planned})))}</div></div><div class="panel"><h3>Funding sources</h3>${table(asArray(plan.funding),[{key:'source',label:'Source'},{key:'note',label:'Notes'},{key:'planned',label:'Planned',render:x=>money(x.planned)}])}</div>`}
function sim(balance,rate,years,extra){const r=rate/1200,months=Math.max(1,Math.round(years*12));if(balance<=0||years<=0||rate<0||rate>100)return null;const emi=r?balance*r/(1-(1+r)**(-months)):balance/months;if(!Number.isFinite(emi))return null;let b=balance,interest=0,m=0;while(b>.01&&m<1200){let charge=b*r;interest+=charge;const payment=Math.min(b+charge,emi+extra);b=Math.max(0,b+charge-payment);m++;if(payment<=charge)return null}return {emi,interest,months:m,finish:b<.01}}
function schedule(){let l=plan.loan;return `<div class="panel"><h3>Loan payoff scenario</h3><p class="hint">Uses a fixed monthly rate for an estimate, not the lender's actual floating-rate or construction-linked schedule. It starts from the balance entered below, not sanctioned amount; excludes fees and future disbursements.</p><div class="fields"><label>Outstanding balance (₹)<input id="outstanding" type="number" min="0" value="${esc(l.outstanding||0)}"></label><label>Annual interest (%)<input id="rate" type="number" min="0" max="100" step=".01" value="${esc(l.rate||0)}"></label><label>Remaining term (years)<input id="tenureYears" type="number" min=".1" max="100" step=".1" value="${esc(l.tenureYears||15)}"></label><label>Extra each month (₹)<input id="extraMonthly" type="number" min="0" value="${esc(l.extraMonthly||0)}"></label></div><button class="primary" id="calculate">Update scenario</button><div id="simulation"></div></div>`}
function updateSimulation(){const l=plan.loan,b=Number(l.outstanding),r=Number(l.rate),y=Number(l.tenureYears),extra=Number(l.extraMonthly),base=sim(b,r,y,0),scenario=sim(b,r,y,extra);$('simulation').innerHTML=(!base||!scenario)?'<p class="alert">Enter a positive outstanding balance and a valid interest rate/term to compare payments.</p>':`<div class="cards" style="margin-top:22px">${card('Baseline EMI',money(base.emi),'Constant-rate estimate')}${card('Baseline payoff',`${base.months} months`,money(base.interest)+' interest')}${card('With extra payment',`${scenario.months} months`,money(scenario.interest)+' interest')}${card('Estimated saving',money(base.interest-scenario.interest),`${base.months-scenario.months} months earlier`)}</div><p class="hint">Rate changes, payment dates, lender rounding and future disbursements will change actual results.</p>`}
function records(){return `<div class="grid2"><div class="panel"><h3>Emergency reserve</h3><p>Current: <strong>${money(plan.emergency?.currentFund)}</strong></p><p>Target: <strong>${money(Number(plan.emergency?.monthlyEssentials||0)*Number(plan.emergency?.targetMonths||0))}</strong></p></div><div class="panel"><h3>Project details</h3><p>${esc(plan.loan.notes||'No project notes entered.')}</p></div></div><div class="panel"><h3>Family records</h3>${table(asArray(plan.family),[{key:'name',label:'Name'},{key:'relation',label:'Relation'},{key:'dependency',label:'Dependency'}])}</div><div class="panel"><h3>Insurance cover</h3>${table(asArray(plan.insurance),[{key:'name',label:'Name'},{key:'type',label:'Type'},{key:'sumInsured',label:'Cover',render:x=>money(x.sumInsured)}])}</div><div class="panel"><h3>Actions</h3>${table(asArray(plan.actions),[{key:'description',label:'Action'},{key:'status',label:'Status'}])}</div>`}
function render(){if(!plan)return;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=({overview,ledger,plans,schedule,records}[tab])();if(tab==='schedule'){if(window.planOrigin==='owner')$('calculate').disabled=true;$('calculate').onclick=()=>{if(window.planOrigin==='owner'){notify('Private plan is read-only in this preview.');return}for(const k of ['outstanding','rate','tenureYears','extraMonthly']){let n=Number($(k).value);if(!Number.isFinite(n)||n<0){notify('Enter non-negative numbers.');return}plan.loan[k]=n}save()};updateSimulation()}}
try{const stored=localStorage.getItem(KEY);if(stored){show(JSON.parse(stored),'saved');notify('This browser has a saved plan. It has not been uploaded.')}}catch{localStorage.removeItem(KEY)}
// Editable local plan. Additions are saved only on this device and to explicit downloads.
const editFields={loan:[['lender','Lender','text'],['loanAccountNumber','Loan account number','text'],['projectCost','Project cost (₹)','number'],['sanctioned','Sanctioned loan (₹)','number'],['disbursed','Total disbursed (₹)','number'],['outstanding','Outstanding loan (₹)','number'],['rate','Annual rate (%)','number'],['tenureYears','Remaining term (years)','number'],['repaymentStart','Repayment start','date'],['emiDueDay','EMI due day','number'],['extraMonthly','Extra monthly payment (₹)','number'],['annualLumpSum','Annual lump sum (₹)','number'],['lumpSumMonth','Lump-sum month (1-12)','number'],['emiStepUpPercent','Annual EMI step-up (%)','number'],['targetDebtFree','Target debt-free date','date'],['preEmiUntil','Full EMI transition date','date'],['notes','Project notes','text']],emergency:[['monthlyEssentials','Monthly essentials (₹)','number'],['targetMonths','Reserve months','number'],['currentFund','Current reserve (₹)','number'],['monthlyContribution','Monthly contribution (₹)','number'],['sinkingFund','Other sinking funds (₹)','number']]};
const entryFields={contractor:[['date','Date','date'],['payee','Payee','text'],['category','Category','text'],['amount','Amount (₹)','number'],['source','Funding source','text'],['mode','Payment mode','text'],['note','Reference / note','text']],indirectExpenses:[['date','Date','date'],['description','Description','text'],['category','Category','text'],['amount','Amount (₹)','number'],['source','Funding source','text']],budget:[['category','Category','text'],['planned','Budget (₹)','number']],indirectBudget:[['category','Category','text'],['planned','Budget (₹)','number']],funding:[['source','Source','text'],['planned','Planned (₹)','number']],disbursements:[['date','Date','date'],['amount','Amount (₹)','number'],['note','Reference / note','text']],prepayments:[['date','Date','date'],['amount','Amount (₹)','number'],['note','Reference / note','text']],actions:[['description','Action','text'],['status','Status','text']],insurance:[['name','Policy name','text'],['type','Type','text'],['provider','Provider','text'],['sumInsured','Cover (₹)','number'],['premium','Premium (₹)','number'],['renewal','Renewal','date']],family:[['name','Name','text'],['relation','Relationship','text'],['dependency','Dependency','text']]};
function fieldsFor(def,prefix,obj){return def.map(([key,label,type])=>`<label>${esc(label)}<input data-key="${esc(key)}" id="${prefix}${esc(key)}" type="${type}" ${type==='number'?'min="0" step="any"':''} value="${esc(obj?.[key]??'')}"></label>`).join('')}
function edit(){return `<div class="panel"><h3>Loan details</h3><div class="editor">${fieldsFor(editFields.loan,'loan-',plan.loan)}</div><div class="editor-actions"><button class="primary" id="save-loan">Save loan details</button></div></div><div class="panel"><h3>Emergency reserve</h3><div class="editor">${fieldsFor(editFields.emergency,'emergency-',plan.emergency||{})}</div><div class="editor-actions"><button class="primary" id="save-emergency">Save reserve</button></div></div><div class="panel"><h3>Ledger and planning entries</h3><p class="hint">Add an entry to your plan, then export a backup. Editing a JSON import stays local to this browser. Frozen records from an imported plan are read-only here; change them in your source of truth.</p><label>Section<select id="entry-section">${Object.keys(entryFields).map(k=>`<option value="${k}">${esc(({indirectExpenses:'Indirect expenses',indirectBudget:'Indirect budget'}[k]||k))}</option>`).join('')}</select></label><div id="entry-fields" class="editor" style="margin-top:20px"></div><div class="editor-actions"><button class="primary" id="add-entry">Add entry</button></div><div id="entry-list"></div></div>`}
function mountEdit(){for(const section of Object.keys(editFields)){$('save-'+section).onclick=()=>{const obj=plan[section]||(plan[section]={});for(const [key,label,type] of editFields[section]){const val=$(section+'-'+key).value;if(type==='number'&&(!Number.isFinite(Number(val))||Number(val)<0)){notify(`${label} must be a non-negative number.`);return}obj[key]=type==='number'?Number(val):val}save()}}const selector=$('entry-section');function updateSection(){const section=selector.value,def=entryFields[section];$('entry-fields').innerHTML=fieldsFor(def,'entry-',{});const rows=asArray(plan[section]);$('entry-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr>${def.map(x=>`<th>${esc(x[1])}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((row,i)=>`<tr>${def.map(([key,,type])=>`<td>${esc(type==='number'?money(row[key]):row[key])}</td>`).join('')}<td>${row.frozen?'<span class="pill">Frozen</span>':`<button class="row-delete" data-index="${i}">Remove</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No entries yet.</div>';$('entry-list').querySelectorAll('button[data-index]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this entry?'))return;plan[section].splice(Number(b.dataset.index),1);save()})}selector.onchange=updateSection;updateSection();$('add-entry').onclick=()=>{const section=selector.value,row={};for(const [key,label,type] of entryFields[section]){const value=$('entry-'+key).value;if(type==='number'&&(!Number.isFinite(Number(value))||Number(value)<0)){notify(`${label} must be a non-negative number.`);return}row[key]=type==='number'?Number(value):value}if(!Object.values(row).some(v=>v&&v!==0)){notify('Enter at least one field to add an entry.');return}plan[section]=asArray(plan[section]);plan[section].push(row);save()}}
// Replace the first render implementation with an extension preserving the existing views.
const originalRender=render;
render=function(){if(!plan)return;if(tab==='edit'&&window.planOrigin==='owner'){tab='overview';notify('Private plan is read-only in this preview.')}if(tab==='edit'){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=edit();mountEdit()}else originalRender()};

window.show=show;window.clearLoadedPlan=()=>{plan=null;document.getElementById('workspace').hidden=true;document.getElementById('intro').hidden=false};
// Native full-depth workspace extension. Every visitor mutation is local-only.
const UI={section:'contractor',editIndex:null};
const SECTIONS={contractor:'Contractor payment',indirectExpenses:'Indirect expense',budget:'Direct budget category',indirectBudget:'Indirect budget category',funding:'Funding source',disbursements:'Loan disbursement',prepayments:'Prepayment',actions:'Follow-up action',insurance:'Insurance policy',family:'Family member'};
const INSURANCE_FULL=[['name','Policy name','text'],['type','Type','text'],['structure','Structure','text'],['covers','Who or what it covers','text'],['provider','Provider','text'],['sumInsured','Sum insured (₹)','number'],['deductible','Deductible (₹)','number'],['premium','Premium (₹)','number'],['renewal','Renewal date','date'],['notes','Exclusions, nominees and notes','text']];
const ACTIONS_FULL=[['title','What needs to happen?','text'],['due','Due date','date'],['owner','Who is responsible?','text'],['status','Status','text'],['category','Category','text'],['note','Next step / reference','text']];
const FAMILY_FULL=[['name','Name','text'],['relation','Relationship','text'],['dob','Date of birth','date'],['dependency','Role / dependency','text'],['notes','Notes','text']];
const ENTRY_FULL={...entryFields,insurance:INSURANCE_FULL,actions:ACTIONS_FULL,family:FAMILY_FULL,disbursements:[['date','Date','date'],['stage','Construction milestone','text'],['payee','Paid to / contractor','text'],['reference','Bank reference','text'],['amount','Amount (₹)','number']],prepayments:[['date','Date','date'],['source','Source','text'],['note','Note','text'],['amount','Amount (₹)','number']],budget:[['category','Direct construction category','text'],['planned','Planned amount (₹)','number'],['note','Scope note','text']],indirectBudget:[['category','Indirect / carrying cost category','text'],['planned','Planned amount (₹)','number'],['note','Assumption','text']],funding:[['source','Funding source','text'],['planned','Planned amount (₹)','number'],['note','Availability / conditions','text']],indirectExpenses:[['date','Date','date'],['description','Description','text'],['category','Indirect cost category','text'],['source','Funding source','text'],['note','Reference','text'],['amount','Amount (₹)','number']]};
const GO_TABS={loan:'edit',contractor:'ledger',insurance:'insurance'};
function goTo(section){if(window.planOrigin==='owner'){notify('Private data is read-only until cloud editing is tested.');return}if(!plan)show(TEMPLATE,'blank');UI.section=section;UI.editIndex=null;tab='edit';render();if(tab==='edit'){const sel=$('entry-section');if(sel&&ENTRY_FULL[section]){sel.value=section;sel.dispatchEvent(new Event('change'));requestAnimationFrame(()=>document.querySelector('#record-editor')?.scrollIntoView({behavior:'smooth',block:'start'}))}else requestAnimationFrame(()=>document.querySelector('#view')?.scrollIntoView({behavior:'smooth',block:'start'}))}}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>goTo(b.dataset.go));
const priorShow=show;window.show=function(p,label){priorShow(p,label);if(label==='blank'){notify('Start with the actions above. Your changes save only on this device.');}};
function insuranceView(){const rows=asArray(plan.insurance),health=sum(rows.filter(x=>x.type==='Health'),'sumInsured'),life=sum(rows.filter(x=>x.type==='Term Life'),'sumInsured');const soon=rows.filter(x=>x.renewal&&new Date(x.renewal+'T00:00:00')>=new Date(new Date().toDateString())&&new Date(x.renewal+'T00:00:00')<new Date(Date.now()+30*86400000)).length;return `<div class="section-head"><div><h3>Insurance & protection</h3><p>List health, life and home cover. Record who is covered, the deductible, premium and renewal date.</p></div><button class="section-action" data-add="insurance">+ Add policy</button></div><div class="cards">${card('Health cover',money(health),`${rows.filter(x=>x.type==='Health').length} policies`)}${card('Term life cover',money(life),`${rows.filter(x=>x.type==='Term Life').length} policies`)}${card('Renewals in 30 days',String(soon),'Review dates')}${card('Policies',String(rows.length),'Your local register')}</div><div class="panel"><h3>Policy register</h3>${rows.length?rows.map((r,i)=>`<div class="policy-row"><div><strong>${esc(r.name||'Untitled policy')}</strong><div class="hint">${esc(r.type||'Other')} · ${esc(r.structure||'Structure not entered')} · ${esc(r.provider||'Provider not entered')}</div><div>Cover ${money(r.sumInsured)} · Premium ${money(r.premium)} · Renews ${esc(r.renewal||'date not entered')}</div><div class="hint">Covers: ${esc(r.covers||'Not entered')} · Deductible ${money(r.deductible)}${r.notes?` · ${esc(r.notes)}`:''}</div></div><div class="entry-tools">${r.frozen?'<span class="freeze-tag">Locked</span>':''}<button data-edit="insurance:${i}" ${r.frozen?'disabled':''}>Edit</button><button data-freeze="insurance:${i}">${r.frozen?'Unlock':'Lock'}</button><button data-delete="insurance:${i}" ${r.frozen?'disabled':''}>Delete</button></div></div>`).join(''):'<div class="empty"><p>No insurance policies yet.</p><p>Add any health, life or property cover you rely on, then check renewal dates.</p><button class="section-action" data-add="insurance">+ Add your first policy</button></div>'}</div>`}
function actionsAndFamilyView(){const family=asArray(plan.family),actions=asArray(plan.actions);return `<div class="grid2"><div class="panel"><div class="section-head"><div><h3>Family & co-applicants</h3><p>Keep the people affected by your plan together.</p></div><button class="section-action" data-add="family">+ Add person</button></div>${genericRows('family',family,['name','relation','dependency'])}</div><div class="panel"><div class="section-head"><div><h3>Follow-ups</h3><p>Bank paperwork, contractor milestones and renewals to chase.</p></div><button class="section-action" data-add="actions">+ Add action</button></div>${genericRows('actions',actions,['title','due','status'])}</div></div><div class="panel"><div class="section-head"><div><h3>Emergency reserve</h3><p>Keep a cash buffer before committing more to construction or prepayment.</p></div><button class="section-action" data-add="emergency">Edit reserve</button></div><p>Current ${money(plan.emergency?.currentFund)} · Target ${money(Number(plan.emergency?.monthlyEssentials||0)*Number(plan.emergency?.targetMonths||0))}</p></div>`}
function genericRows(section,rows,keys){return rows.length?rows.map((r,i)=>`<div class="policy-row"><div><strong>${esc(r[keys[0]]||'Untitled')}</strong><div class="hint">${esc(r[keys[1]]||'')} · ${esc(r[keys[2]]||'')}</div></div><div class="entry-tools">${r.frozen?'<span class="freeze-tag">Locked</span>':''}<button data-edit="${section}:${i}" ${r.frozen?'disabled':''}>Edit</button><button data-freeze="${section}:${i}">${r.frozen?'Unlock':'Lock'}</button><button data-delete="${section}:${i}" ${r.frozen?'disabled':''}>Delete</button></div></div>`).join(''):'<div class="empty">Nothing added yet.</div>'}
function bindEntryActions(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>goTo(b.dataset.add));for(const type of ['edit','freeze','delete'])document.querySelectorAll(`[data-${type}]`).forEach(b=>b.onclick=()=>{const [section,raw]=b.dataset[type].split(':'),i=Number(raw),row=plan[section]?.[i];if(!row)return;if(type==='edit'){if(row.frozen)return;goTo(section);UI.editIndex=i;const fields=ENTRY_FULL[section];for(const [key] of fields){const el=$('entry-'+key);if(el)el.value=row[key]??''}const add=$('add-entry');if(add)add.textContent='Save changes';notify(`Editing ${SECTIONS[section]}. Save changes below.`);return}if(type==='freeze'){if(!confirm(`${row.frozen?'Unlock':'Lock'} this ${SECTIONS[section]}? ${row.frozen?'It will become editable again.':'Edits and deletion will be blocked until you unlock it.'}`))return;row.frozen=!row.frozen;row.frozenAt=row.frozen?new Date().toISOString():null;save();return}if(type==='delete'){if(row.frozen)return;if(!confirm(`Delete this ${SECTIONS[section]}? This cannot be undone.`))return;plan[section].splice(i,1);save()}})}
// Render overrides keep overview/simulator, add visible contextual editing throughout.
const coreRender=render;
render=function(){if(!plan)return;if(tab==='insurance'){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=insuranceView();bindEntryActions();return}if(tab==='records'){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=actionsAndFamilyView();bindEntryActions();return}coreRender();if(tab==='ledger'||tab==='plans'||tab==='overview'){
  const view=$('view');if(tab==='ledger')view.insertAdjacentHTML('afterbegin',`<div class="section-head"><div><h3>Payments & cost control</h3><p>Direct payments go to the contractor ledger. Temporary rent, legal fees and carrying costs go to indirect costs.</p></div><div class="entry-tools"><button data-add="contractor">+ Contractor payment</button><button data-add="indirectExpenses">+ Indirect expense</button></div></div>`);
  if(tab==='plans')view.insertAdjacentHTML('afterbegin',`<div class="section-head"><div><h3>Budget, funding & disbursements</h3><p>Plan direct construction separately from indirect costs. Record bank releases by milestone, then compare funds with actual spend.</p></div><div class="entry-tools"><button data-add="budget">+ Direct budget</button><button data-add="indirectBudget">+ Indirect budget</button><button data-add="funding">+ Funding</button><button data-add="disbursements">+ Bank release</button></div></div>`);
  if(tab==='overview')view.insertAdjacentHTML('afterbegin',`<div class="section-head"><div><h3>Start with the full picture</h3><p>Enter the loan terms, budget and funding first. Keep the emergency reserve and insurance current before planning extra repayments.</p></div><button class="section-action" data-add="loan">Edit loan details</button></div>`);bindEntryActions();}}
const nativeEdit=edit;
edit=function(){let markup=nativeEdit();markup=markup.replace('<div class="panel"><h3>Ledger and planning entries</h3>','<div class="panel" id="record-editor"><h3>Add or update a record</h3>');return markup};
const nativeMountEdit=mountEdit;
mountEdit=function(){nativeMountEdit();const select=$('entry-section');if(!select)return;select.innerHTML=Object.keys(ENTRY_FULL).map(k=>`<option value="${k}">${esc(SECTIONS[k])}</option>`).join('');
  const nativeOnChange=select.onchange;
  select.onchange=()=>{UI.section=select.value;UI.editIndex=null;const fields=ENTRY_FULL[select.value];$('entry-fields').innerHTML=fieldsFor(fields,'entry-',{});$('add-entry').textContent='Add '+SECTIONS[select.value];$('entry-list').innerHTML=genericRows(select.value,asArray(plan[select.value]),fields.slice(0,3).map(x=>x[0]));bindEntryActions()};
  select.value=ENTRY_FULL[UI.section]?UI.section:'contractor';select.onchange();
  $('add-entry').onclick=()=>{const section=select.value,fields=ENTRY_FULL[section],row={};for(const [key,label,type] of fields){const input=$('entry-'+key),val=input?.value??'';if(type==='number'&&(!Number.isFinite(Number(val))||Number(val)<0)){notify(`${label} must be a non-negative number.`);return}row[key]=type==='number'?Number(val):val}if(!Object.values(row).some(v=>v!==''&&v!==0)){notify('Enter a value before saving.');return}plan[section]=asArray(plan[section]);const index=UI.editIndex;if(index!==null&&plan[section][index]&&!plan[section][index].frozen)plan[section][index]={...plan[section][index],...row,updatedAt:new Date().toISOString()};else plan[section].push({...row,frozen:false});UI.editIndex=null;save();notify(`Saved ${SECTIONS[section]} on this device.`)};
};

function lifePlan(){const x=plan.life||{};const baseline=Number(plan.emergency?.monthlyEssentials||0),extra=Number(x.educationMonthly||0)+Number(x.parentsCareMonthly||0),monthly=baseline+extra,months=Number(plan.emergency?.targetMonths||6),target=monthly*months+Number(x.healthReserve||0);return `<div class="panel"><div class="section-head"><div><h3>Life outside the loan</h3><p>Optional planning inputs. Keep essentials, children’s education and parents’ care in view before choosing an extra loan payment.</p></div></div><div class="editor">${[['educationMonthly','Children’s education per month (₹)','number'],['parentsCareMonthly','Parents’ care per month (₹)','number'],['healthReserve','Extra health reserve (₹)','number'],['annualInflation','Inflation assumption (%)','number']].map(([key,label,type])=>`<label>${esc(label)}<input id="life-${key}" type="${type}" min="0" step="any" value="${esc(x[key]??0)}"></label>`).join('')}</div><div class="editor-actions"><button class="primary" id="life-save">Save life planning</button></div><div class="mini-guide" style="margin-top:16px">With these inputs, a ${esc(months)}-month reserve target is ${money(target)}. This is a planning estimate; include only costs not already counted in monthly essentials to avoid double counting.</div></div>`}
const beforeRenderLife=render;
render=function(){beforeRenderLife();if(!plan)return;if(tab==='records'||tab==='schedule'){let view=$('view');view.insertAdjacentHTML('beforeend',lifePlan());$('life-save').onclick=()=>{if(window.planOrigin==='owner'){notify('Private plan read-only during testing.');return}plan.life=plan.life||{};for(const key of ['educationMonthly','parentsCareMonthly','healthReserve','annualInflation']){const n=Number($('life-'+key).value);if(!Number.isFinite(n)||n<0){notify('Use non-negative numbers.');return}plan.life[key]=n}save()}}};
// In-place controls keep editing next to each ledger row rather than hidden in Edit plan.
function detailedRows(section,fields){const rows=asArray(plan[section]);if(!rows.length)return '<div class="empty">No entries yet. Use Add to record your first one.</div>';return rows.map((r,i)=>`<div class="policy-row"><div class="record-fields">${fields.map(([key,label,type])=>`<div><span>${esc(label)}</span><strong>${esc(type==='number'?money(r[key]):r[key]||'Not entered')}</strong></div>`).join('')}</div><div class="entry-tools">${r.frozen?'<span class="freeze-tag">Locked</span>':''}<button data-edit="${section}:${i}" ${r.frozen?'disabled':''}>Edit</button><button data-freeze="${section}:${i}">${r.frozen?'Unlock':'Lock'}</button><button data-delete="${section}:${i}" ${r.frozen?'disabled':''}>Delete</button></div></div>`).join('')}
function ledgerDetailView(){return `<div class="section-head"><div><h3>Payments & cost control</h3><p>Construction payments and indirect costs stay in separate ledgers. Edit or lock a record beside its details.</p></div></div><div class="cards">${card('Contractor paid',money(sum(plan.contractor)),`${asArray(plan.contractor).length} entries`)}${card('Indirect costs',money(sum(plan.indirectExpenses)),`${asArray(plan.indirectExpenses).length} entries`)}${card('Disbursed',money(sum(plan.disbursements)),'Recorded bank releases')}${card('Prepaid',money(sum(plan.prepayments)),'Recorded extra payments')}</div>${[['contractor','Contractor payments'],['indirectExpenses','Indirect expenses'],['prepayments','Prepayments']].map(([section,title])=>`<div class="panel"><div class="section-head"><h3>${title}</h3><button class="section-action" data-add="${section}">+ Add ${SECTIONS[section].toLowerCase()}</button></div>${detailedRows(section,ENTRY_FULL[section])}</div>`).join('')}`}
function planningDetailView(){return `<div class="section-head"><div><h3>Budget, funding & bank releases</h3><p>Keep direct construction, indirect costs and funding apart. Edit or lock each line alongside its details.</p></div></div>${[['budget','Construction budget'],['indirectBudget','Indirect cost budget'],['funding','Funding sources'],['disbursements','Bank releases']].map(([section,title])=>`<div class="panel"><div class="section-head"><h3>${title}</h3><button class="section-action" data-add="${section}">+ Add ${SECTIONS[section].toLowerCase()}</button></div>${detailedRows(section,ENTRY_FULL[section])}</div>`).join('')}`}
const renderBeforeDetails=render;
render=function(){if(!plan)return;if(tab==='ledger'||tab==='plans'){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=tab==='ledger'?ledgerDetailView():planningDetailView();bindEntryActions();return}renderBeforeDetails()};

// Stage selection guides the workspace, never deletes a previous stage's records.
const STAGES={planning:{title:'Planning to buy or build',sub:'Compare the budget, loan terms and family cash buffer before committing.',tabs:['overview','plans','schedule','insurance','records','edit'],actions:['loan','insurance']},constructing:{title:'Applying for a construction loan or building',sub:'Track loan approval, bank releases and construction spending as work happens.',tabs:['overview','ledger','plans','schedule','insurance','records','edit'],actions:['loan','insurance','contractor']},repaying:{title:'Already paying a home loan',sub:'Focus on EMI, prepayments, protection and the life costs alongside your loan.',tabs:['overview','ledger','schedule','insurance','records','edit'],actions:['loan','insurance']}};
function hasConstructionHistory(){return ['contractor','indirectExpenses','budget','indirectBudget','disbursements'].some(k=>asArray(plan?.[k]).length)}
function stageChoices(){return `<div class="stage-intro"><span class="eyebrow">MAKE THIS PLAN FIT YOU</span><h3>Where are you in your home-loan journey?</h3><p>Choose what to focus on. You can change this later; your saved entries stay in the plan.</p></div><div class="stage-options">${Object.entries(STAGES).map(([id,x],i)=>`<button class="stage-option" data-stage="${id}"><span>0${i+1} /</span><strong>${x.title}</strong><small>${x.sub}</small><b>Choose this stage →</b></button>`).join('')}</div>`}
function syncStageUI(){if(!plan)return;const id=plan.meta?.stage,valid=!!STAGES[id],pick=$('stage-picker'),current=$('stage-current');pick.hidden=valid;current.hidden=!valid;document.querySelector('.quickstart').hidden=!valid;document.querySelector('.tabs').hidden=!valid;$('view').hidden=!valid;if(!valid){pick.innerHTML=stageChoices();pick.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>chooseStage(b.dataset.stage));pick.scrollIntoView({block:'start',behavior:'smooth'});return}
 const stage=STAGES[id],history=id==='repaying'&&hasConstructionHistory();current.innerHTML=`<div><span class="eyebrow">CURRENT STAGE</span><strong>${stage.title}</strong><small>${stage.sub}</small></div><button id="change-stage" type="button">Change stage</button>`;$('change-stage').onclick=()=>{pick.hidden=false;pick.innerHTML=stageChoices();pick.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>chooseStage(b.dataset.stage));pick.scrollIntoView({block:'start',behavior:'smooth'})};
 document.querySelectorAll('.tabs button').forEach(b=>{let t=b.dataset.tab;b.hidden=!(stage.tabs.includes(t)||(t==='history'&&history));if(t==='ledger'&&id==='repaying')b.textContent='Prepayments';else if(t==='ledger')b.textContent='Payments'});
 const quick=document.querySelector('.quickstart');quick.querySelector('strong').textContent=id==='planning'?'Plan before you borrow':id==='constructing'?'Track each construction cost':'Keep your repayment plan current';quick.querySelector('p').textContent=stage.sub;quick.querySelectorAll('[data-go]').forEach(b=>b.hidden=!stage.actions.includes(b.dataset.go));}
function chooseStage(id){if(!STAGES[id]||!plan)return;if(window.planOrigin==='owner'){notify('Private plan stage cannot be changed in this preview.');return}plan.meta=plan.meta||{};plan.meta.stage=id;tab='overview';save();notify(`Showing ${STAGES[id].title.toLowerCase()} sections. Your earlier entries were kept.`)}
function stageHistory(){return `<div class="section-head"><div><h3>Construction-stage history</h3><p>Expenses and bank releases entered while building remain here after you move to repayment. They do not become current monthly EMI costs.</p></div></div>${[['contractor','Construction payments'],['indirectExpenses','Construction-stage indirect costs'],['budget','Original construction budget'],['indirectBudget','Original indirect cost budget'],['disbursements','Bank releases']].map(([section,title])=>`<div class="panel"><h3>${title}</h3>${detailedRows(section,ENTRY_FULL[section])}</div>`).join('')}`}
const renderBeforeStage=render;
render=function(){if(!plan)return;const id=plan.meta?.stage;if(id==='repaying'&&tab==='ledger'){$('view').innerHTML=`<div class="section-head"><div><h3>Prepayments</h3><p>Extra payments against your current loan. Construction spending stays in its own history.</p></div><button class="section-action" data-add="prepayments">+ Add prepayment</button></div><div class="panel">${detailedRows('prepayments',ENTRY_FULL.prepayments)}</div>`;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bindEntryActions()}else if(tab==='history'){$('view').innerHTML=stageHistory();document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bindEntryActions()}else renderBeforeStage();syncStageUI()};
$('start').onclick=()=>{show(TEMPLATE,'blank');notify('Choose your stage to set up the right workspace.')};
if(plan)render();

// Landing stage choices start a new local plan. Existing saved plans stay intact unless explicitly closed.
document.querySelectorAll('[data-start-stage]').forEach(b=>b.onclick=()=>{if(plan){notify('Close or export your current plan before starting a new one.');$('workspace').scrollIntoView({behavior:'smooth'});return}show(TEMPLATE,'blank');chooseStage(b.dataset.startStage);$('workspace').scrollIntoView({behavior:'smooth'})});
$('start').onclick=()=>document.querySelector('#landing-stage').scrollIntoView({behavior:'smooth'});

// A stage needs a short setup, not just a button. Disbursements are a funding proxy, not certified physical completion.
function stageQuestionMarkup(id){const x=plan.stageSetup||{};return `<div class="stage-intro"><span class="eyebrow">${esc(STAGES[id].title.toUpperCase())}</span><h3>Tell us what has happened so far</h3><p>These answers shape your dashboard. You can update them later.</p></div><div class="stage-form"><label>Is your loan sanctioned?<select id="q-sanctioned"><option value="">Choose one</option><option value="yes" ${x.sanctioned==='yes'?'selected':''}>Yes</option><option value="no" ${x.sanctioned==='no'?'selected':''}>No</option><option value="pending" ${x.sanctioned==='pending'?'selected':''}>Application pending</option></select></label><label>Have EMI payments started?<select id="q-emi-started"><option value="">Choose one</option><option value="yes" ${x.emiStarted==='yes'?'selected':''}>Yes</option><option value="no" ${x.emiStarted==='no'?'selected':''}>No</option><option value="pre-emi" ${x.emiStarted==='pre-emi'?'selected':''}>Interest-only / pre-EMI</option></select></label><label>Next payment date <small>(if known)</small><input id="q-next-payment" type="date" value="${esc(x.nextPaymentDate||'')}"></label>${id==='constructing'?`<label>Total planned construction cost (₹)<input id="q-construction-cost" type="number" min="0" step="any" value="${esc(x.constructionCost||'')}"><small>Used only as a denominator for a bank-release-based funding indicator.</small></label>`:''}<div class="stage-form-actions"><button id="q-back" type="button">Back to stages</button><button id="q-save" type="button">See my dashboard</button></div></div>`}
function openStageQuestions(id){if(!STAGES[id]||!plan)return;const form=$('stage-questions');form.hidden=false;form.innerHTML=stageQuestionMarkup(id);$('stage-picker').hidden=true;document.querySelector('.quickstart').hidden=true;document.querySelector('.tabs').hidden=true;$('view').hidden=true;$('stage-current').hidden=true;$('q-back').onclick=()=>{form.hidden=true;syncStageUI();$('stage-picker').hidden=false};$('q-save').onclick=()=>{const sanctioned=$('q-sanctioned').value,emiStarted=$('q-emi-started').value,nextPaymentDate=$('q-next-payment').value,cost=id==='constructing'?Number($('q-construction-cost').value||0):Number(plan.stageSetup?.constructionCost||0);if(!sanctioned||!emiStarted){notify('Choose loan-sanction and EMI status to continue.');return}if(!Number.isFinite(cost)||cost<0){notify('Enter a valid construction cost.');return}plan.stageSetup={...plan.stageSetup,sanctioned,emiStarted,nextPaymentDate,constructionCost:cost};plan.meta=plan.meta||{};plan.meta.stage=id;form.hidden=true;tab='overview';save();notify('Dashboard tailored to your answers. You can change them later.');$('stage-current').scrollIntoView({behavior:'smooth',block:'start'})};form.scrollIntoView({behavior:'smooth',block:'start'})}
// Make stage choices lead to a setup form before committing the stage.
chooseStage=function(id){openStageQuestions(id)};
document.querySelectorAll('[data-start-stage]').forEach(b=>b.onclick=()=>{if(plan){notify('Close or export your current plan before starting a new one.');$('workspace').scrollIntoView({behavior:'smooth'});return}show(TEMPLATE,'blank');openStageQuestions(b.dataset.startStage)});
const syncBeforeQuestions=syncStageUI;
syncStageUI=function(){if($('stage-questions')&&!$('stage-questions').hidden)return;syncBeforeQuestions();if(!plan?.meta?.stage)return;const button=$('change-stage');if(button){button.textContent='Update stage & answers';button.onclick=()=>{const pick=$('stage-picker');pick.hidden=false;pick.innerHTML=stageChoices();pick.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>openStageQuestions(b.dataset.stage));pick.scrollIntoView({behavior:'smooth',block:'start'})}}};
function stageDashboard(){const s=plan.stageSetup||{},id=plan.meta?.stage,l=plan.loan||{},releases=sum(plan.disbursements),denom=Number(s.constructionCost||0),progress=denom>0?Math.min(100,releases/denom*100):null;let cards='';if(id==='constructing'){cards+=card('Loan status',plan.profile?.appliedLoan==='no'?'Not applied':s.sanctioned==='yes'?'Sanctioned':s.sanctioned==='pending'?'Application pending':'Not sanctioned','Your answer');cards+=card('EMI status',plan.profile?.appliedLoan==='no'?'No loan yet':s.emiStarted==='yes'?'Started':s.emiStarted==='pre-emi'?'Pre-EMI only':'Not started','Your answer');cards+=card('Bank releases recorded',money(releases),'Funding logged against construction');cards+=card('Release-based progress',progress===null?'Set planned cost':`${progress.toFixed(1)}%`,'Bank releases ÷ planned construction cost')}else if(id==='repaying'){const baseline=sim(Number(l.outstanding),Number(l.rate),Number(l.tenureYears),0);cards+=card('Outstanding loan',money(l.outstanding),'Entered balance');cards+=card('Estimated monthly EMI',baseline?money(baseline.emi):'Add loan terms','Estimate from balance, rate and term');cards+=card('EMI status',plan.profile?.appliedLoan==='no'?'No loan yet':s.emiStarted==='yes'?'Started':s.emiStarted==='pre-emi'?'Pre-EMI only':'Not started','Your answer');cards+=card('Prepayments recorded',money(sum(plan.prepayments)),'Extra payments')}else{cards+=card('Loan status',plan.profile?.appliedLoan==='no'?'Not applied':s.sanctioned==='yes'?'Sanctioned':s.sanctioned==='pending'?'Application pending':'Not sanctioned','Your answer');cards+=card('Planned project cost',money(l.projectCost),'Enter loan details to refine');cards+=card('Planned funding',money(sum(plan.funding,'planned')),'Funding sources added');cards+=card('EMI status',plan.profile?.appliedLoan==='no'?'No loan yet':s.emiStarted==='yes'?'Started':s.emiStarted==='pre-emi'?'Pre-EMI only':'Not started','Your answer')}
 return `<div class="section-head"><div><h3>${esc(STAGES[id].title)} dashboard</h3><p>${esc(STAGES[id].sub)}</p></div></div><div class="cards">${cards}</div><div class="panel"><h3>${id==='constructing'?'How construction and loan payments connect':id==='repaying'?'Repayment next steps':'Before you commit'}</h3>${s.nextPaymentDate?`<p>Next payment date entered: <strong>${esc(s.nextPaymentDate)}</strong>. Confirm it with your lender or bank.</p>`:'<p>No next payment date entered yet.</p>'}${id==='constructing'?'<p class="hint">The release-based percentage is disbursed funding divided by the planned construction cost you entered. It is not a physical construction-completion percentage and cannot verify a milestone. Enter bank-to-contractor releases under Budget & funding; compare against actual work before paying.</p>':id==='repaying'?'<p class="hint">This EMI is a fixed-rate estimate, not your lender statement. Earlier construction spending stays under Construction history if present.</p>':'<p class="hint">You can update the loan terms and budget as quotes and approvals come in.</p>'}</div>`}
const renderBeforeDashboard=render;
render=function(){if(plan?.meta?.stage&&tab==='overview'){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('view').innerHTML=stageDashboard();syncStageUI();return}renderBeforeDashboard()};

// First-timer path: stage choices appear only after the user asks to set up a new plan.
$('start').onclick=()=>{if(plan){notify('A plan is already open. Export or close it before starting another.');$('workspace').scrollIntoView({behavior:'smooth'});return}const panel=$('landing-stage');panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'start'})};
document.querySelectorAll('[data-start-stage]').forEach(b=>b.onclick=()=>{if(plan){notify('Export or close your current plan before starting another.');return}show(TEMPLATE,'blank');openStageQuestions(b.dataset.startStage)});
// Replaces the all-at-once questionnaire with one answered item at a time.
const QUESTION_STEPS=[{key:'sanctioned',label:'Is your loan sanctioned?',options:[['yes','Yes'],['no','No'],['pending','Application pending']]},{key:'emiStarted',label:'Have EMI payments started?',options:[['yes','Yes'],['no','No'],['pre-emi','Interest-only / pre-EMI']]},{key:'nextPaymentDate',label:'When is your next loan payment?',type:'date',optional:true},{key:'constructionCost',label:'What is the planned construction cost?',type:'number',construction:true,optional:true}];
let pendingStage=null,answerStep=0,pendingAnswers={};
function displayQuestion(){const step=QUESTION_STEPS.filter(q=>!q.construction||pendingStage==='constructing')[answerStep];if(!step)return finishAnswers();const all=QUESTION_STEPS.filter(q=>!q.construction||pendingStage==='constructing'),value=pendingAnswers[step.key]??'';const form=$('stage-questions');form.hidden=false;form.innerHTML=`<div class="stage-intro"><span class="eyebrow">FIRST-TIMER SETUP · ${answerStep+1} OF ${all.length}</span><h3>${esc(step.label)}</h3><p>${step.key==='constructionCost'?'This is only for a bank-release funding indicator. It does not measure work completed.':step.key==='nextPaymentDate'?'Leave this blank if the bank has not confirmed a date.':'Choose one answer to continue.'}</p></div><div class="question-one">${step.options?`<div class="question-options">${step.options.map(([val,label])=>`<button type="button" data-answer="${val}" ${value===val?'class="selected"':''}>${label}</button>`).join('')}</div>`:`<label>${esc(step.label)}<input id="question-value" type="${step.type}" ${step.type==='number'?'min="0" step="any"':''} value="${esc(value)}" ${step.type==='number'?'placeholder="₹"':''}></label>`}<div class="question-navigation"><button type="button" id="question-back">${answerStep?'Previous question':'Back to stages'}</button>${step.options?'':`<button type="button" id="question-next">${answerStep===all.length-1?'See my dashboard':'Next question →'}</button>`}</div></div>`;form.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{pendingAnswers[step.key]=b.dataset.answer;answerStep++;displayQuestion()});$('question-back').onclick=()=>{if(answerStep){answerStep--;displayQuestion()}else{form.hidden=true;const pick=$('stage-picker');pick.hidden=false;pick.innerHTML=stageChoices();pick.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>openStageQuestions(b.dataset.stage))}};if(!step.options)$('question-next').onclick=()=>{const v=$('question-value').value;if(step.type==='number'&&v!==''&&(!Number.isFinite(Number(v))||Number(v)<0)){notify('Enter a non-negative amount.');return}pendingAnswers[step.key]=step.type==='number'?Number(v||0):v;answerStep++;displayQuestion()};form.scrollIntoView({behavior:'smooth',block:'start'})}
function finishAnswers(){if(window.planOrigin==='owner'){notify('Private plan is read-only.');return}plan.meta=plan.meta||{};plan.meta.stage=pendingStage;plan.stageSetup={...plan.stageSetup,...pendingAnswers};plan.meta.firstTimerCompleted=true;$('stage-questions').hidden=true;tab='overview';save();notify('Your first-timer answers are saved in this plan and its JSON export. You can update them later.');$('stage-current').scrollIntoView({behavior:'smooth',block:'start'})}
openStageQuestions=function(id){if(!STAGES[id]||!plan)return;pendingStage=id;answerStep=0;pendingAnswers={...plan.stageSetup};$('stage-picker').hidden=true;$('stage-current').hidden=true;document.querySelector('.quickstart').hidden=true;document.querySelector('.tabs').hidden=true;$('view').hidden=true;displayQuestion()};
// Readiness math holds purchase price and rate fixed: rent is still paid while renting, never counted as savings.
function monthsForGap(gap,monthly){return gap<=0?0:monthly>0?Math.ceil(gap/monthly):null}
function planningMetrics(){const x=plan.readiness||{},price=Number(x.price),deposit=Number(x.deposit),saving=Number(x.saving),rent=Number(x.rent),emiBudget=Number(x.emiBudget),rate=Number(x.rate),years=Number(x.years),target10=.1*price,target20=.2*price,redirect=Math.max(0,emiBudget-rent-saving),accelerated=saving+redirect,m10=monthsForGap(target10-deposit,accelerated),m20=monthsForGap(target20-deposit,accelerated),b10=price-target10,b20=price-target20,a=sim(b10,rate,years,0),b=sim(b20,rate,years,0),delay=m10===null||m20===null?null:Math.max(0,m20-m10),interestSaved=a&&b?a.interest-b.interest:null,rentDelay=delay===null?null:delay*rent;return {target10,target20,redirect,accelerated,m10,m20,a,b,delay,interestSaved,rentDelay}}
function planningCoach(){const x=plan.readiness||{},hasPrice=Number(x.price)>0,haveModel=hasPrice&&x.years!==''&&x.years!=null&&Number(x.years)>0&&x.rate!==''&&x.rate!=null&&Number(x.rate)>=0&&x.deposit!==''&&x.deposit!=null&&Number(x.deposit)>=0&&Number(x.deposit)<Number(x.price),m=hasPrice?planningMetrics():null;return `<div class="panel readiness"><h3>Check your down payment before borrowing</h3><p class="hint">Explore 10% and 20% down payment scenarios. These are comparison points, not a universal lender requirement. Add your own numbers; no example amount is treated as your money.</p><div class="readiness-fields">${[['price','Property / project price (₹)'],['deposit','Down payment saved now (₹)'],['saving','Monthly savings while renting (₹)'],['rent','Monthly rent while waiting (₹)'],['emiBudget','Affordable monthly rent + saving budget (₹)'],['rate','Illustrative loan interest rate (%)'],['years','Loan term (years)']].map(([key,label])=>`<label>${esc(label)}<input id="ready-${key}" type="number" min="0" step="any" value="${esc(x[key]??'')}"></label>`).join('')}</div><button id="readiness-save" class="primary">Calculate with my numbers</button>${hasPrice?`<div class="readiness-results"><div class="cards">${card('10% down payment',money(m.target10),`You have ${money(x.deposit||0)} saved`)}${card('20% down payment',money(m.target20),'Higher deposit reduces borrowed amount')}${card('Extra monthly saving',money(m.redirect),'Only if the budget includes current savings and still covers essentials')}${card('Total saving while waiting',money(m.accelerated),'Current saving + possible extra')}</div>${haveModel?`<div class="grid2"><div class="panel"><h3>Buy at 10% down</h3><p>Time to target: <strong>${m.m10===null?'Not reachable at current saving rate':`${m.m10} months`}</strong></p><p>Estimated EMI: <strong>${m.a?money(m.a.emi):'Need valid loan terms'}</strong></p><p>Estimated full-term interest: <strong>${m.a?money(m.a.interest):'Need valid loan terms'}</strong></p></div><div class="panel"><h3>Wait for 20% down</h3><p>Time to target: <strong>${m.m20===null?'Not reachable at current saving rate':`${m.m20} months`}</strong></p><p>Estimated EMI: <strong>${m.b?money(m.b.emi):'Need valid loan terms'}</strong></p><p>Estimated full-term interest: <strong>${m.b?money(m.b.interest):'Need valid loan terms'}</strong></p></div></div>${m.delay!==null&&m.interestSaved!==null?`<div class="mini-guide">Waiting about ${m.delay} extra months to reach 20% down may cut estimated monthly EMI by ${money(m.a.emi-m.b.emi)} and full-term loan interest by ${money(m.interestSaved)}. Rent during those extra months would be ${money(m.rentDelay)} at the entered rent. This is not net savings: property prices, rent increases, taxes, fees, investment returns and changing interest rates are not modeled.</div>`:''}`:'<div class="mini-guide">Enter down payment, monthly saving, rate and loan term to compare time and borrowing cost.</div>'}</div>`:'<div class="mini-guide">Enter a property price and your savings to see your readiness.</div>'}<p class="hint">Monthly extra saving is max(0, comfortable housing budget − current rent − current saving). Rent remains a cost until you move; the tool does not pretend it can be saved while you still rent.</p></div>`}
const renderBeforeReadiness=render;
render=function(){renderBeforeReadiness();if(plan?.meta?.stage==='planning'&&tab==='overview'&&!$('view').hidden){$('view').insertAdjacentHTML('beforeend',planningCoach());$('readiness-save').onclick=()=>{const vals={};for(const key of ['price','deposit','saving','rent','emiBudget','rate','years']){const input=$('ready-'+key),n=Number(input.value);if(input.value!==''&&(!Number.isFinite(n)||n<0)){notify('Use non-negative numbers for the readiness calculation.');return}vals[key]=input.value===''?'':n}if(vals.price>0&&vals.deposit>=vals.price){notify('Down payment should be less than the property price for a loan comparison.');return}if(vals.price>0&&vals.emiBudget!==''&&vals.rent!==''&&vals.saving!==''&&vals.emiBudget<vals.rent+vals.saving){notify('Your rent plus current savings exceed the budget entered. Check those amounts before calculating.');return}plan.readiness=vals;save();notify('Readiness figures updated on this device. Export JSON to keep a copy.')};}}

// Questionnaire v2: branching by project, funding, housing and construction. Nothing is sent to a server.
const BASE_STEPS=[{key:'purpose',label:'What are you planning?',options:[['buy','Buy a ready home'],['construct','Construct on land'],['buy-build','Buy land and build'],['mixed','Build a home with commercial space'],['own','Manage a home I already own']]},{key:'stage',label:'Where are you today?',options:[['planning','Still planning'],['applying','Applying for a loan / permits'],['building','Construction underway'],['repaying','Already paying the loan'],['owned','Home completed']]},{key:'fundingMode',label:'How will you fund this?',options:[['own','Own savings or family funds, no loan'],['loan','Mostly with a loan'],['mixed','Own funds and a loan'],['unsure','Not decided yet']]},{key:'housing',label:'Where do you live now?',options:[['rent','Renting'],['own','Own home'],['other','Other / prefer not to say']]},{key:'location',label:'Where does the household income come from?',options:[['india','India'],['abroad','Outside India'],['mixed','Both'],['skip','Prefer not to say']]},{key:'priority',label:'What matters most?',options:[['liquidity','Keep enough cash available'],['cost','Control the total project cost'],['debtfree','Become debt-free sooner'],['compare','Compare borrowing options']]}];
let branchedAnswers={},branchedIndex=0,branchedEdit=false;
function needsConstruction(q){return ['construct','buy-build','mixed'].includes(q.purpose)}
function usesLoan(q){return q.fundingMode==='loan'||q.fundingMode==='mixed'}
function hasLoanApplication(q){return usesLoan(q)&&q.appliedLoan==='yes'}
function hasSanctionedLoan(q){return hasLoanApplication(q)&&q.sanctioned==='yes'}
function branchSteps(q){const steps=[BASE_STEPS[0],BASE_STEPS[1],BASE_STEPS[2]];
 if(usesLoan(q))steps.push({key:'appliedLoan',label:'Have you applied for this home loan?',options:[['yes','Yes'],['no','No, not yet']]});
 if(hasLoanApplication(q))steps.push({key:'sanctioned',label:'Has a lender sanctioned this loan?',options:[['yes','Yes'],['pending','Application pending'],['no','No, not sanctioned']]});
 if(hasSanctionedLoan(q)){steps.push({key:'emiStarted',label:'Have payments on this loan started?',options:[['yes','Full EMI started'],['pre-emi','Only interest / pre-EMI'],['no','Not yet']]});if(q.emiStarted==='yes'||q.emiStarted==='pre-emi')steps.push({key:'nextPaymentDate',label:'When is the next loan payment?',type:'date',optional:true})}
 if(q.fundingMode==='own')steps.push({key:'considerLoan',label:'Would you compare paying cash with taking a loan and investing your funds?',options:[['yes','Yes, compare both paths'],['no','No, pay cash without borrowing']]});
 if(needsConstruction(q)){steps.push({key:'areaBasis',label:'How is the floor area stated?',options:[['total','Total built-up area across all floors'],['per-floor','Area per floor']]},{key:'areaSqft',label:'How many square feet is that area?',type:'number'});if(q.areaBasis==='per-floor')steps.push({key:'floorCount',label:'How many floors will be built?',type:'number'});steps.push({key:'contractorRate',label:'What is the contractor quote per square foot (₹)?',type:'number'},{key:'interiors',label:'Rough interiors budget (₹)?',type:'number',optional:true})}
 steps.push(BASE_STEPS[3]);if(q.housing==='rent')steps.push({key:'rent',label:'What is the monthly rent (₹)?',type:'number',optional:true});steps.push(BASE_STEPS[4]);if(q.location==='abroad'||q.location==='mixed')steps.push({key:'incomeCurrency',label:'Which currency do you earn in?',options:[['SAR','Saudi riyal (SAR)'],['USD','US dollar (USD)'],['other','Another currency']]});if(q.purpose==='mixed')steps.push({key:'commercialArea',label:'How much of the total built-up area is commercial (sq ft)?',type:'number',optional:true});steps.push(BASE_STEPS[5]);return steps}
// Remove answers which no longer belong to the chosen path; never touch ledger entries.
function pruneBranchAnswers(){const active=new Set(branchSteps(branchedAnswers).map(x=>x.key));for(const key of ['appliedLoan','sanctioned','emiStarted','nextPaymentDate','considerLoan','areaBasis','areaSqft','floorCount','contractorRate','interiors','rent','incomeCurrency','commercialArea'])if(!active.has(key))delete branchedAnswers[key]}
function advanceBranch(key,value){branchedAnswers[key]=value;pruneBranchAnswers();branchedIndex=branchSteps(branchedAnswers).findIndex(x=>x.key===key)+1;branchQuestion()}

function branchStage(q){if(q.stage==='repaying')return 'repaying';if(q.stage==='owned')return needsConstruction(q)?'repaying':'planning';if(q.stage==='building'||q.stage==='applying')return needsConstruction(q)?'constructing':'planning';return 'planning'}
function branchFeatures(q){const construction=needsConstruction(q),loan=usesLoan(q);return [{name:'Property & budget',show:true,why:'Relevant to every property plan'},{name:'Construction costs & contractor',show:construction,why:construction?'You are building or planning to build':'Not building in this plan'},{name:'Loan & EMI',show:loan,why:loan?'You plan to use a loan':'No actual loan is planned'},{name:'Cash versus invest-and-borrow (planned)',show:q.fundingMode==='own'&&q.considerLoan==='yes',why:q.fundingMode==='own'&&q.considerLoan==='yes'?'Requested as a future scenario; no calculation is shown yet':'Optional comparison, not an assumed loan'},{name:'Down-payment & rent comparison',show:q.housing==='rent'&&loan,why:q.housing==='rent'&&loan?'You rent and may borrow':'Shown when you rent and plan a loan'},{name:'NRI remittance (planned)',show:q.location==='abroad'||q.location==='mixed',why:q.location==='abroad'||q.location==='mixed'?'Your income includes another country':'No cross-border income entered'},{name:'Mixed-use allocation (planned)',show:q.purpose==='mixed',why:q.purpose==='mixed'?'You selected home plus commercial space':'No mixed use entered'}]}
function constructionRoughCost(q){if(!needsConstruction(q))return null;const area=Number(q.areaSqft),floors=q.areaBasis==='total'?1:Number(q.floorCount),rate=Number(q.contractorRate),interiors=Number(q.interiors)||0;if(!(area>0&&floors>0&&rate>0)||!['total','per-floor'].includes(q.areaBasis))return null;const builtUp=q.areaBasis==='per-floor'?area*floors:area;return {builtUp,base:builtUp*rate,interiors,total:builtUp*rate+interiors}}
function branchSummary(q){const cost=constructionRoughCost(q),features=branchFeatures(q);return `<div class="branch-summary"><h3>Your plan, shaped by your answers</h3><p>These topics fit your answers. More tools will arrive in later versions; change your answers without losing records.</p><div class="branch-features">${features.filter(x=>x.show).map(x=>`<div class="on"><strong>${esc(x.name)}</strong><small>${esc(x.why)}</small></div>`).join('')}</div>${cost?`<div class="mini-guide">Rough construction cost: ${money(cost.base)} for ${esc(cost.builtUp)} total built-up sq ft at ${money(q.contractorRate)} per sq ft, plus ${money(cost.interiors)} interiors = ${money(cost.total)}. This excludes land, approvals, utilities, changes, tax and finance costs unless included in the quote. Confirm what the contractor quote covers.</div>`:needsConstruction(q)?'<div class="mini-guide">Enter area basis, floor count and contractor rate for a rough construction estimate.</div>':''}</div>`}
function branchQuestion(){const steps=branchSteps(branchedAnswers),step=steps[branchedIndex];if(!step)return branchFinish();const form=$('stage-questions'),val=branchedAnswers[step.key]??'';form.hidden=false;form.innerHTML=`<div class="stage-intro"><span class="eyebrow">FIRST-TIMER PROFILE · ${branchedIndex+1} OF ${steps.length}</span><h3>${esc(step.label)}</h3><p>${step.key==='areaBasis'?'Choose carefully: total area is not multiplied by the number of floors again.':step.key==='fundingMode'?'A loan is optional. Cash-funded plans skip EMI questions.':'Only relevant follow-up questions appear.'}</p></div><div class="question-one">${step.options?`<div class="question-options">${step.options.map(([v,label])=>`<button type="button" data-branch-answer="${esc(v)}" ${val===v?'class="selected"':''}>${esc(label)}</button>`).join('')}</div>`:`<label>${esc(step.label)}<input id="branch-value" type="${step.type}" ${step.type==='number'?'min="0" step="any"':''} value="${esc(val)}"></label>`}<div class="question-navigation"><button id="branch-back" type="button">${branchedIndex?'Previous question':'Back to stages'}</button>${step.options?'':`<button id="branch-next" type="button">${branchedIndex===steps.length-1?'Finish':'Next question →'}</button>`}</div></div>`;form.querySelectorAll('[data-branch-answer]').forEach(b=>b.onclick=()=>advanceBranch(step.key,b.dataset.branchAnswer));$('branch-back').onclick=()=>{if(branchedIndex){branchedIndex--;branchQuestion()}else{form.hidden=true;const pick=$('stage-picker');pick.hidden=false;pick.innerHTML=stageChoices();pick.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>openStageQuestions(b.dataset.stage))}};if(!step.options)$('branch-next').onclick=()=>{const v=$('branch-value').value,n=Number(v);if(step.type==='number'&&v!==''&&(!Number.isFinite(n)||n<0)){notify('Enter a non-negative number.');return}if(!step.optional&&v===''){notify('Enter this answer to continue.');return}if(step.key==='floorCount'&&(!Number.isInteger(n)||n<1||n>100)){notify('Enter a whole number of floors.');return}advanceBranch(step.key,step.type==='number'?(v===''?'':n):v)};form.scrollIntoView({behavior:'smooth',block:'start'})}
function branchFinish(){if(window.planOrigin==='owner'){notify('Private plan is read-only.');return}plan.meta=plan.meta||{};plan.meta.stage=branchStage(branchedAnswers);plan.meta.firstTimerCompleted=true;plan.meta.questionnaireVersion=2;pruneBranchAnswers();plan.profile={...branchedAnswers};plan.stageSetup={...plan.stageSetup,sanctioned:branchedAnswers.sanctioned||'',emiStarted:branchedAnswers.emiStarted||'',nextPaymentDate:branchedAnswers.nextPaymentDate||'',constructionCost:constructionRoughCost(branchedAnswers)?.total||0};if(branchedAnswers.rent!==''&&branchedAnswers.rent!=null)plan.readiness={...plan.readiness,rent:branchedAnswers.rent};$('stage-questions').hidden=true;tab='overview';save();notify('Your answers are saved in the JSON. Relevant sections are shown; hidden sections keep their history.');$('stage-current').scrollIntoView({behavior:'smooth',block:'start'})}
openStageQuestions=function(id){if(!plan)return;branchedAnswers={...plan.profile,purpose:plan.profile?.purpose||({planning:'buy',constructing:'construct',repaying:'own'}[id])};branchedIndex=0;branchedEdit=!!plan.meta?.firstTimerCompleted;pruneBranchAnswers();$('stage-picker').hidden=true;$('stage-current').hidden=true;document.querySelector('.quickstart').hidden=true;document.querySelector('.tabs').hidden=true;$('view').hidden=true;branchQuestion()};
const stageUISource=syncStageUI;
syncStageUI=function(){stageUISource();if(!plan?.meta?.stage||!$('stage-questions').hidden)return;const q=plan.profile||{},uses=usesLoan(q),construction=needsConstruction(q),stage=plan.meta.stage;if(q.fundingMode==='own'){document.querySelector('[data-tab="schedule"]').hidden=q.considerLoan!=='yes';document.querySelector('[data-tab="ledger"]').hidden=stage!=='constructing';document.querySelector('.quickstart p').textContent='Self-funded plan: focus on cash and project cost. A loan comparison appears only if you choose to explore it.'}if(!construction&&stage==='planning'){document.querySelector('[data-tab="plans"]').hidden=false}const button=$('change-stage');if(button){button.textContent='Update your answers';button.onclick=()=>openStageQuestions(stage)}};
const renderBeforeBranch=render;
render=function(){renderBeforeBranch();if(!plan?.meta?.firstTimerCompleted||tab!=='overview'||$('view').hidden)return;$('view').insertAdjacentHTML('afterbegin',branchSummary(plan.profile||{}));const q=plan.profile||{};if(!usesLoan(q)&&plan.meta.stage==='planning'){$('view').querySelector('.readiness')?.remove()}};
// Keep exploratory leverage separate from an actual mortgage until its scenario model is built.
function cashFundedDashboard(){const q=plan.profile||{},rough=constructionRoughCost(q),spent=sum(plan.contractor)+sum(plan.indirectExpenses),reserve=Number(plan.emergency?.currentFund)||0;return `<div class="section-head"><div><h3>Self-funded home plan</h3><p>Focus on construction cost, committed spending and the cash you want to keep safe.</p></div></div><div class="cards">${card('Rough project cost',rough?money(rough.total):'Add a cost estimate','Contractor quote + interiors only')}${card('Construction spending',money(spent),'Recorded direct + indirect expenses')}${card('Cash reserve entered',money(reserve),'Edit reserve as needed')}${card('Funding approach','Own / family funds','No loan is assumed')}</div><div class="panel"><h3>Keep borrowing as a choice</h3>${q.considerLoan==='yes'?'<p>You asked to compare paying cash with investing your funds and taking a loan. That comparison is planned but not calculated here. It needs the same time horizon, loan rate and fees, after-tax investment returns, possible losses and reserve needs. A higher expected return alone does not prove borrowing is better.</p>':'<p>Your profile does not include a loan. Loan and EMI tools stay out of this plan unless you change the funding answer.</p>'}<p class="hint">Your existing records remain in the JSON when your funding choice changes.</p></div>`}
const renderBeforeCash=render;
render=function(){renderBeforeCash();if(plan?.meta?.firstTimerCompleted&&plan.profile?.fundingMode==='own'){document.querySelector('[data-tab="schedule"]').hidden=true;if(tab==='overview'&&!$('view').hidden){$('view').innerHTML=branchSummary(plan.profile)+cashFundedDashboard()}}};
// The saved plan is opened before all render layers are installed; finish restoring its UI now.
if(plan)render();
const syncBeforeFundingUI=syncStageUI;
syncStageUI=function(){syncBeforeFundingUI();if(!plan?.meta?.firstTimerCompleted||!$('stage-questions').hidden)return;const q=plan.profile||{},self=q.fundingMode==='own',stage=plan.meta.stage,construction=needsConstruction(q),current=$('stage-current');if(self){document.querySelector('[data-tab="schedule"]').hidden=true;document.querySelector('[data-tab="ledger"]').hidden=!construction&&stage!=='repaying';if(construction)document.querySelector('[data-tab="plans"]').hidden=false;current.querySelector('strong').textContent=stage==='repaying'?'Completed home plan':stage==='constructing'?'Building a home':'Planning a home';current.querySelector('small').textContent='Self-funded: track the project and reserve without assuming a loan.';const quick=document.querySelector('.quickstart');quick.querySelector('strong').textContent='Track your home project';quick.querySelector('p').textContent='Add spending and funding as they happen. Keep a reserve for life outside the project.';quick.querySelector('[data-go="loan"]').hidden=true}else if(stage==='repaying'&&q.stage==='owned'){current.querySelector('strong').textContent='Completed home plan';current.querySelector('small').textContent='Track current payments while keeping past construction records.'}};
const renderBeforeFundingUI=render;
render=function(){renderBeforeFundingUI();if(plan?.meta?.firstTimerCompleted)syncStageUI()};
// Returning visitors can run first-time setup against their existing local plan.
// Never replace a saved plan just to enter onboarding.
$('start').onclick=()=>{const panel=$('landing-stage');panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'start'});if(plan)notify('Your saved plan is open. Set up a profile without losing its existing records.')};
document.querySelectorAll('[data-start-stage]').forEach(b=>b.onclick=()=>{if(!plan)show(TEMPLATE,'blank');openStageQuestions(b.dataset.startStage)});
